mapper.insert:
INSERT INTO shopping_cart (name, image, user_id, dish_id,
                           setmeal_id, dish_flavor, amount, create_time,number)
VALUES ( #{name}, #{image}
       , #{userId}, #{dishId},
         #{setmealId}, #{dishFlavor}
       , #{amount}, #{createTime},#{number})

mapper.select:
SELECT * FROM shopping_cart

    dish_id = #{dishId}
    AND setmeal_id = #{setmealId}
    AND dish_flavor = #{dishFlavor}
    AND user_id=#{userId}

mapper.update:
UPDATE shopping_cart
name =#{name}, dish_id =#{dishId}, setmeal_id =#{setmealId}, dish_flavor =#{dishFlavor}, number =#{number}, amount =#{amount}, image =#{image}, create_time =#{createTime},
WHERE id = #{id}
